/**
 * The facial hair the hair pack ships from MakeHuman's CC0 community assets (issue 110,
 * ruling 8): five authored meshes bound to the base mesh, not cards generated by code.
 * The hair pack's own tests cover every entry's binding; these cover what is specific to
 * the beards: which are there, where they came from, and that each one binds like a
 * clothes asset (three base vertices a vertex, weights summing to one).
 */
import fs from "node:fs";
import path from "node:path";
import { describe, expect, it } from "vitest";
import { bodyManifest } from "./fixtures.ts";
import { hairDir, hairManifest, loadHairFixtureAssets } from "./hairFixtures.ts";

/** Pack id, then the community asset it is compiled from (bodyparts05, `Facialhair`, CC0 by its pack record). */
const ASSET_BEARDS = [
  ["beard-faun", "culturalibre_faun_beard"],
  ["beard-sigmund", "grinsegold_beard_sigmund_wip"],
  ["beard-viking", "rehmanpolanski_beard_viking"],
  ["moustache-viking", "rehmanpolanski_moustache_viking"],
  ["beard-scruffy", "wdg_scruffy_beard"],
] as const;

const provenance = fs.readFileSync(path.join(hairDir, "PROVENANCE.md"), "utf8");

describe("the grafted facial hair", () => {
  it("ships the five bodyparts05 assets as beard entries", () => {
    for (const [id] of ASSET_BEARDS) {
      const entry = hairManifest.styles.find((s) => s.id === id);
      expect(entry, id).toBeDefined();
      expect(entry?.kind, id).toBe("beard");
    }
  });

  it("names each source asset and the pinned archive in the provenance", () => {
    expect(provenance).toContain("bodyparts05");
    for (const [, asset] of ASSET_BEARDS) expect(provenance, asset).toContain(asset);
  });

  it("binds every vertex to three base vertices that exist, with weights summing to one", () => {
    const assets = loadHairFixtureAssets();
    for (const [id] of ASSET_BEARDS) {
      const entry = hairManifest.styles.find((s) => s.id === id);
      const bound = assets.hair?.bound.get(id);
      expect(bound, id).toBeDefined();
      if (!entry || !bound) continue;
      expect(bound.refVerts.length, id).toBe(entry.vertexCount * 3);
      expect(Math.max(...bound.refVerts), id).toBeLessThan(bodyManifest.vertexCount);
      let worst = 0;
      for (let v = 0; v < entry.vertexCount; v++) {
        const sum =
          (bound.weights[v * 3] as number) +
          (bound.weights[v * 3 + 1] as number) +
          (bound.weights[v * 3 + 2] as number);
        worst = Math.max(worst, Math.abs(sum - 1));
      }
      expect(worst, id).toBeLessThan(1e-4);
    }
  });

  it("keeps each beard under its source's vertex count, not a resample", () => {
    const expected: Record<string, number> = {
      "beard-faun": 5218,
      "beard-sigmund": 503,
      "beard-viking": 6557,
      "moustache-viking": 1598,
      "beard-scruffy": 2300,
    };
    for (const [id, count] of Object.entries(expected)) {
      const entry = hairManifest.styles.find((s) => s.id === id);
      expect(entry?.vertexCount, id).toBe(count);
    }
  });
});
